from __future__ import annotations

from abc import ABC, abstractmethod
from typing import Any, Dict


class DataProcessor(ABC):
    """Abstract base class defining a data processing contract."""

    @abstractmethod
    def process(self, data: Dict[str, Any]) -> str:
        """Process input data and return a string result."""
        pass


class JsonDataProcessor(DataProcessor):
    """Processor implementation that serializes data to JSON-like output."""

    def process(self, data: Dict[str, Any]) -> str:
        return str(data)


class CsvDataProcessor(DataProcessor):
    """Processor implementation that serializes data to CSV-like output."""

    def process(self, data: Dict[str, Any]) -> str:
        return ",".join(str(value) for value in data.values())


class StorageBackend(ABC):
    """Abstract base class defining a storage contract."""

    @abstractmethod
    def save(self, item: str) -> str:
        """Save an item and return a status message."""
        pass


class FileStorage(StorageBackend):
    """Concrete storage implementation writing items to a file."""

    def save(self, item: str) -> str:
        return f"saved: {item}"


def process_data(processor: DataProcessor, data: Dict[str, Any]) -> str:
    """Process data using the provided abstract processor."""
    return processor.process(data)


def save_storage(storage: StorageBackend, item: str) -> str:
    """Save an item using the provided storage backend."""
    return storage.save(item)


def main() -> None:
    """Main function demonstrating abstract base class usage."""
    json_result = process_data(JsonDataProcessor(), {"name": "Alice", "age": 30})
    csv_result = process_data(CsvDataProcessor(), {"name": "Alice", "age": 30})
    saved_result = save_storage(FileStorage(), "report.txt")

    print("JSON-style result:", json_result)
    print("CSV-style result:", csv_result)
    print("Storage result:", saved_result)


if __name__ == "__main__":
    main()

from __future__ import annotations


def add_binary(a: str, b: str) -> str:
    """Add two binary strings and return the binary sum."""
    i, j = len(a) - 1, len(b) - 1
    carry = 0
    result: list[str] = []

    while i >= 0 or j >= 0 or carry:
        total = carry
        if i >= 0:
            total += int(a[i])
            i -= 1
        if j >= 0:
            total += int(b[j])
            j -= 1
        result.append(str(total % 2))
        carry = total // 2

    return "".join(reversed(result))


def main() -> None:
    """Main function demonstrating add_binary examples."""
    examples = [
        ("1010", "1011"),
        ("0", "0"),
        ("1111", "1"),
        ("100", "110010"),
    ]
    for a, b in examples:
        print(f"{a} + {b} -> {add_binary(a, b)}")


if __name__ == "__main__":
    main()

from __future__ import annotations

import re
from collections import Counter


def normalize_text(text: str, ignore_non_alphanumeric: bool = True) -> str:
    """Normalize text for anagram checking."""
    normalized = text.lower().strip()
    if ignore_non_alphanumeric:
        normalized = re.sub(r"[^a-z0-9]", "", normalized)
    return normalized


def is_anagram(first: str, second: str, ignore_non_alphanumeric: bool = True) -> bool:
    """Return True if the two strings are anagrams."""
    normalized_first = normalize_text(first, ignore_non_alphanumeric)
    normalized_second = normalize_text(second, ignore_non_alphanumeric)
    if len(normalized_first) != len(normalized_second):
        return False
    return Counter(normalized_first) == Counter(normalized_second)


def is_anagram_sorted(first: str, second: str, ignore_non_alphanumeric: bool = True) -> bool:
    """Return True if the two strings are anagrams using sorting."""
    normalized_first = normalize_text(first, ignore_non_alphanumeric)
    normalized_second = normalize_text(second, ignore_non_alphanumeric)
    return sorted(normalized_first) == sorted(normalized_second)


def main() -> None:
    """Main function demonstrating anagram checks."""
    examples = [
        ("listen", "silent"),
        ("triangle", "integral"),
        ("hello", "world"),
    ]
    for first, second in examples:
        print(first, second, "->", is_anagram(first, second))
        print(first, second, "sorted ->", is_anagram_sorted(first, second))


if __name__ == "__main__":
    main()

from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import List, Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def average_of_levels(root: Optional[TreeNode]) -> List[float]:
    """Return the average value of nodes at each tree level."""
    if not root:
        return []

    averages: List[float] = []
    queue = deque([root])

    while queue:
        level_size = len(queue)
        level_sum = 0
        for _ in range(level_size):
            node = queue.popleft()
            level_sum += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        averages.append(level_sum / level_size)

    return averages


def main() -> None:
    root = TreeNode(3, left=TreeNode(9), right=TreeNode(20, left=TreeNode(15), right=TreeNode(7)))
    print("Level averages:", average_of_levels(root))


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Tuple


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def is_balanced(root: Optional[TreeNode]) -> bool:
    """Return True if the binary tree is height-balanced."""
    def check(node: Optional[TreeNode]) -> Tuple[bool, int]:
        if node is None:
            return True, 0
        left_balanced, left_height = check(node.left)
        if not left_balanced:
            return False, 0
        right_balanced, right_height = check(node.right)
        if not right_balanced:
            return False, 0
        return abs(left_height - right_height) <= 1, 1 + max(left_height, right_height)

    balanced, _ = check(root)
    return balanced


def main() -> None:
    root1 = TreeNode(3, left=TreeNode(9), right=TreeNode(20, left=TreeNode(15), right=TreeNode(7)))
    root2 = TreeNode(1, left=TreeNode(2, left=TreeNode(3, left=TreeNode(4), right=TreeNode(4)), right=TreeNode(3)), right=TreeNode(2))
    print(is_balanced(root1))
    print(is_balanced(root2))


if __name__ == "__main__":
    main()

from __future__ import annotations

from typing import List


def calculate(s: str) -> int:
    """Evaluate a basic arithmetic expression with +, -, *, /."""
    stack: List[int] = []
    num = 0
    sign = '+'
    s = s.replace(' ', '')

    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num * 10 + int(ch)
        if ch in '+-*/' or i == len(s) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                top = stack.pop()
                stack.append(int(top / num))
            sign = ch
            num = 0

    return sum(stack)


def main() -> None:
    print('3+2*2 =', calculate('3+2*2'))
    print(' 3/2 ', calculate(' 3/2 '))
    print(' 3+5 / 2 ', calculate(' 3+5 / 2 '))


if __name__ == '__main__':
    main()

