from typing import List


def max_profit(prices: List[int]) -> int:
    min_price = float('inf')
    max_profit = 0
    for price in prices:
        if price < min_price:
            min_price = price
        else:
            max_profit = max(max_profit, price - min_price)
    return max_profit


def main() -> None:
    print('Max profit:', max_profit([7, 1, 5, 3, 6, 4]))
    print('Max profit:', max_profit([7, 6, 4, 3, 1]))


if __name__ == '__main__':
    main()

