from __future__ import annotations

from typing import List


def binary_search(nums: List[int], target: int) -> int:
    """Return the index of target in sorted nums, or -1 if not found."""
    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1


def main() -> None:
    """Main function demonstrating binary search."""
    examples = [
        ([1, 2, 3, 4, 5], 3),
        ([1, 2, 3, 4, 5], 6),
        ([], 1),
    ]
    for nums, target in examples:
        print(nums, "target=", target, "->", binary_search(nums, target))


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


class BSTIterator:
    """Iterator for a binary search tree that returns values in ascending order."""

    def __init__(self, root: Optional[TreeNode]) -> None:
        self.stack: List[TreeNode] = []
        self._push_left_branch(root)

    def _push_left_branch(self, node: Optional[TreeNode]) -> None:
        while node:
            self.stack.append(node)
            node = node.left

    def next(self) -> int:
        node = self.stack.pop()
        value = node.val
        self._push_left_branch(node.right)
        return value

    def has_next(self) -> bool:
        return bool(self.stack)


def main() -> None:
    root = TreeNode(
        7,
        left=TreeNode(3),
        right=TreeNode(15, left=TreeNode(9), right=TreeNode(20)),
    )
    iterator = BSTIterator(root)
    values: List[int] = []
    while iterator.has_next():
        values.append(iterator.next())
    print(values)


if __name__ == "__main__":
    main()

