from __future__ import annotations

from collections import deque
from dataclasses import dataclass
from typing import List, Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def zigzag_level_order(root: Optional[TreeNode]) -> List[List[int]]:
    """Return the zigzag level order traversal of a binary tree."""
    if not root:
        return []

    results: List[List[int]] = []
    queue = deque([root])
    left_to_right = True

    while queue:
        level_size = len(queue)
        level_values: List[int] = []
        for _ in range(level_size):
            node = queue.popleft()
            if left_to_right:
                level_values.append(node.val)
            else:
                level_values.insert(0, node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        results.append(level_values)
        left_to_right = not left_to_right

    return results


def main() -> None:
    root = TreeNode(3, left=TreeNode(9), right=TreeNode(20, left=TreeNode(15), right=TreeNode(7)))
    print("Zigzag level order:", zigzag_level_order(root))


if __name__ == "__main__":
    main()

from __future__ import annotations


def next_index(nums: list[int], current: int) -> int:
    """Compute the next index in the circular array."""
    n = len(nums)
    return (current + nums[current]) % n


def circular_array_loop(nums: list[int]) -> bool:
    """Return True if there is a valid cycle in the circular array."""
    n = len(nums)
    for i in range(n):
        if nums[i] == 0:
            continue

        slow = i
        fast = i
        direction = nums[i] > 0

        while True:
            slow = next_index(nums, slow)
            fast = next_index(nums, fast)
            fast = next_index(nums, fast)
            if nums[slow] == 0 or nums[fast] == 0:
                break
            if (nums[slow] > 0) != direction or (nums[fast] > 0) != direction:
                break
            if slow == fast:
                if slow == next_index(nums, slow):
                    break
                return True

        marker = i
        while nums[marker] != 0 and (nums[marker] > 0) == direction:
            next_pos = next_index(nums, marker)
            nums[marker] = 0
            marker = next_pos

    return False


def main() -> None:
    examples = [
        [2, -1, 1, 2, 2],
        [-1, 2],
        [-2, 1, -1, -2, -2],
        [1, 1, 2],
    ]
    for nums in examples:
        print(f"{nums} -> {circular_array_loop(nums.copy())}")


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def closest_value(root: Optional[TreeNode], target: float) -> Optional[int]:
    """Return the value in the BST closest to the target."""
    closest = None
    closest_diff = float("inf")
    current = root

    while current:
        diff = abs(current.val - target)
        if diff < closest_diff:
            closest_diff = diff
            closest = current.val

        if target < current.val:
            current = current.left
        else:
            current = current.right

    return closest


def main() -> None:
    root = TreeNode(4, left=TreeNode(2, left=TreeNode(1), right=TreeNode(3)), right=TreeNode(5))
    print("Closest value to 3.7:", closest_value(root, 3.7))


if __name__ == "__main__":
    main()

from __future__ import annotations

from typing import List


def coin_change(coins: List[int], amount: int) -> int:
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)
    return dp[amount] if dp[amount] <= amount else -1


def main() -> None:
    print("Fewest coins for 11:", coin_change([1, 2, 5], 11))


if __name__ == "__main__":
    main()

from __future__ import annotations


def combination_sum_3(k: int, n: int) -> list[list[int]]:
    """Return all combinations of k numbers summing to n."""
    result: list[list[int]] = []

    def backtrack(start: int, current: list[int], remaining: int) -> None:
        if len(current) == k:
            if remaining == 0:
                result.append(current.copy())
            return
        for num in range(start, 10):
            if num > remaining:
                break
            current.append(num)
            backtrack(num + 1, current, remaining - num)
            current.pop()

    backtrack(1, [], n)
    return result


def main() -> None:
    print(combination_sum_3(3, 7))
    print(combination_sum_3(3, 9))


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def build_tree(inorder: List[int], postorder: List[int]) -> Optional[TreeNode]:
    """Build a binary tree from inorder and postorder traversal lists."""
    if not inorder or not postorder:
        return None

    inorder_index_map: Dict[int, int] = {value: idx for idx, value in enumerate(inorder)}
    postorder_index = len(postorder) - 1

    def helper(left: int, right: int) -> Optional[TreeNode]:
        nonlocal postorder_index
        if left > right:
            return None

        root_value = postorder[postorder_index]
        root = TreeNode(root_value)
        postorder_index -= 1

        inorder_index = inorder_index_map[root_value]
        root.right = helper(inorder_index + 1, right)
        root.left = helper(left, inorder_index - 1)
        return root

    return helper(0, len(inorder) - 1)


def inorder_traversal(root: Optional[TreeNode]) -> List[int]:
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right) if root else []


def preorder_traversal(root: Optional[TreeNode]) -> List[int]:
    return [root.val] + preorder_traversal(root.left) + preorder_traversal(root.right) if root else []


def main() -> None:
    inorder = [9, 3, 15, 20, 7]
    postorder = [9, 15, 7, 20, 3]
    root = build_tree(inorder, postorder)
    print("Preorder:", preorder_traversal(root))
    print("Inorder:", inorder_traversal(root))


if __name__ == "__main__":
    main()

