def count_primes(n: int) -> int:
    """Return the count of primes less than n."""
    if n < 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p < n:
        if is_prime[p]:
            for multiple in range(p * p, n, p):
                is_prime[multiple] = False
        p += 1
    return sum(is_prime)


def main() -> None:
    examples = [0, 1, 10, 100]
    for n in examples:
        print(f"{n} -> {count_primes(n)}")


