from __future__ import annotations

import functools
import time
from typing import Any, Callable, TypeVar

F = TypeVar("F", bound=Callable[..., Any])


def log_execution(func: F) -> F:
    """Decorator that logs function execution start and end."""

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        function_name = func.__name__
        print(f"Starting execution of {function_name}")
        result = func(*args, **kwargs)
        print(f"Finished execution of {function_name}")
        return result

    return wrapper  # type: ignore[return-value]


def time_execution(func: F) -> F:
    """Decorator that measures how long a function takes to execute."""

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        start_time = time.perf_counter()
        result = func(*args, **kwargs)
        end_time = time.perf_counter()
        elapsed = end_time - start_time
        print(f"{func.__name__} executed in {elapsed:.6f} seconds")
        return result

    return wrapper  # type: ignore[return-value]


def validate_non_zero_division(func: F) -> F:
    """Decorator that validates denominator values before division."""

    @functools.wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        if len(args) >= 2 and args[1] == 0:
            print("Warning: division by zero avoided")
            return None
        if kwargs.get("denominator") == 0:
            print("Warning: division by zero avoided")
            return None
        return func(*args, **kwargs)

    return wrapper  # type: ignore[return-value]


@log_execution
@time_execution
def add(first: int, second: int) -> int:
    """Return the sum of two integers."""
    return first + second


@validate_non_zero_division
def divide(numerator: int, denominator: int) -> Any:
    """Return the result of integer division, or None on zero denominator."""
    return numerator / denominator


def main() -> None:
    """Main function demonstrating decorator behavior."""
    addition_result = add(3, 5)
    division_result = divide(10, 0)
    division_success = divide(10, 2)

    print("Addition result:", addition_result)
    print("Division result with zero denominator:", division_result)
    print("Division result:", division_success)


if __name__ == "__main__":
    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass
class TreeNode:
    """Binary tree node."""
    val: int
    left: Optional["TreeNode"] = None
    right: Optional["TreeNode"] = None


def delete_node(root: Optional[TreeNode], key: int) -> Optional[TreeNode]:
    """Delete a node with the given key from the BST."""
    if root is None:
        return None

    if key < root.val:
        root.left = delete_node(root.left, key)
    elif key > root.val:
        root.right = delete_node(root.right, key)
    else:
        if root.left is None:
            return root.right
        if root.right is None:
            return root.left

        successor = root.right
        while successor.left:
            successor = successor.left
        root.val = successor.val
        root.right = delete_node(root.right, successor.val)

    return root


def inorder_traversal(root: Optional[TreeNode]) -> list[int]:
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right) if root else []


def main() -> None:
    root = TreeNode(
        5,
        left=TreeNode(3, left=TreeNode(2), right=TreeNode(4)),
        right=TreeNode(6, right=TreeNode(7)),
    )
    print("Before deletion:", inorder_traversal(root))
    root = delete_node(root, 3)
    print("After deletion:", inorder_traversal(root))


if __name__ == "__main__":
    main()

from __future__ import annotations

from typing import Any, Optional


class TypedAttribute:
    """Descriptor that validates the type of assigned values."""

    def __init__(self, name: str, expected_type: type) -> None:
        self.name = name
        self.expected_type = expected_type
        self.storage_name = f"_{name}"

    def __get__(self, instance: Any, owner: type) -> Any:
        if instance is None:
            return self
        return getattr(instance, self.storage_name, None)

    def __set__(self, instance: Any, value: Any) -> None:
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} must be of type {self.expected_type.__name__}")
        setattr(instance, self.storage_name, value)

    def __delete__(self, instance: Any) -> None:
        raise AttributeError(f"{self.name} cannot be deleted")


class PositiveInteger:
    """Descriptor that validates values are positive integers."""

    def __init__(self, name: str) -> None:
        self.name = name
        self.storage_name = f"_{name}"

    def __get__(self, instance: Any, owner: type) -> int:
        if instance is None:
            return self
        return getattr(instance, self.storage_name, 0)

    def __set__(self, instance: Any, value: Any) -> None:
        if not isinstance(value, int) or value <= 0:
            raise ValueError(f"{self.name} must be a positive integer")
        setattr(instance, self.storage_name, value)

    def __delete__(self, instance: Any) -> None:
        raise AttributeError(f"{self.name} cannot be deleted")


class User:
    """A user record using descriptors for typed and validated fields."""

    username = TypedAttribute("username", str)
    age = PositiveInteger("age")

    def __init__(self, username: str, age: int) -> None:
        self.username = username
        self.age = age


class Product:
    """A product record with a computed discount property."""

    price = TypedAttribute("price", float)
    discount_rate = TypedAttribute("discount_rate", float)

    def __init__(self, price: float, discount_rate: float) -> None:
        self.price = price
        self.discount_rate = discount_rate

    @property
    def discounted_price(self) -> float:
        return self.price * (1 - self.discount_rate)


def main() -> None:
    """Main function demonstrating descriptor behavior."""
    user = User(username="alice", age=30)
    try:
        user.age = 31
    except ValueError as error:
        print(error)

    product = Product(price=100.0, discount_rate=0.15)

    print("User username:", user.username)
    print("User age:", user.age)
    print("Discounted product price:", product.discounted_price)


if __name__ == "__main__":
    main()

