def erase_overlap_intervals(intervals: list[list[int]]) -> int:
    """Return the minimum number of intervals to remove to avoid overlap."""
    if not intervals:
        return 0

    intervals.sort(key=lambda x: x[1])
    count = 0
    end = intervals[0][1]
    for start, finish in intervals[1:]:
        if start < end:
            count += 1
        else:
            end = finish
    return count


