from typing import List


def eval_rpn(tokens: List[str]) -> int:
    stack: List[int] = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[-1]


def main() -> None:
    print('[2,1,+,3,*] =', eval_rpn(['2', '1', '+', '3', '*']))
    print('[4,13,5,/,+] =', eval_rpn(['4', '13', '5', '/', '+']))


