import bisect
from typing import List


def length_of_lis(nums: List[int]) -> int:
    """Return the length of the longest strictly increasing subsequence."""
    if not nums:
        return 0

    tails: List[int] = []
    for num in nums:
        index = bisect.bisect_left(tails, num)
        if index == len(tails):
            tails.append(num)
        else:
            tails[index] = num
    return len(tails)


