def min_cost_climbing_stairs(cost: List[int]) -> int:
    n = len(cost)
    if n < 2:
        return 0
    first, second = cost[0], cost[1]
    for i in range(2, n):
        current = cost[i] + min(first, second)
        first, second = second, current
    return min(first, second)


