T = TypeVar("T")


def remove_duplicates(values: Iterable[T]) -> List[T]:
    """Return a list with duplicates removed while preserving original order."""
    seen: set[T] = set()
    result: List[T] = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result


