from dataclasses import dataclass
from typing import Optional


@dataclass
class ListNode:
    """Node for a singly linked list."""
    val: int
    next: Optional["ListNode"] = None


def remove_nth_from_end(head: Optional[ListNode], n: int) -> Optional[ListNode]:
    """Remove the n-th node from the end of the list and return the new head."""
    dummy = ListNode(0, head)
    first = dummy
    second = dummy

    for _ in range(n + 1):
        if first:
            first = first.next
    while first:
        first = first.next
        second = second.next

    if second and second.next:
        second.next = second.next.next

    return dummy.next


def build_list(values: list[int]) -> Optional[ListNode]:
    if not values:
        return None
    head = ListNode(values[0])
    current = head
    for value in values[1:]:
        current.next = ListNode(value)
        current = current.next
    return head


def list_to_values(head: Optional[ListNode]) -> list[int]:
    values: list[int] = []
    current = head
    while current:
        values.append(current.val)
        current = current.next
    return values


def main() -> None:
    examples = [
        ([1, 2, 3, 4, 5], 2),
        ([1], 1),
        ([1, 2], 1),
    ]
    for values, n in examples:
        head = build_list(values)
        result = remove_nth_from_end(head, n)
        print(values, "n=", n, "->", list_to_values(result))


