    """Return True if target exists in the sorted 2D matrix."""
    if not matrix or not matrix[0]:
        return False

    rows = len(matrix)
    cols = len(matrix[0])
    left = 0
    right = rows * cols - 1

    while left <= right:
        mid = (left + right) // 2
        row_index = mid // cols
        col_index = mid % cols
