def simplify_path(path: str) -> str:
    parts = path.split('/')
    stack: List[str] = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)


