def is_valid(s: str) -> bool:
    """Return True if the input string has valid parentheses nesting."""
    mapping: Dict[str, str] = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []

    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            stack.append(char)

    return not stack


