from __future__ import annotations

from collections import deque, defaultdict
from typing import Dict, List


def ladder_length(begin_word: str, end_word: str, word_list: List[str]) -> int:
    """Return the length of the shortest transformation sequence."""
    if end_word not in word_list:
        return 0

    word_list = list(set(word_list + [begin_word]))
    adjacency: Dict[str, List[str]] = defaultdict(list)
    word_length = len(begin_word)

    for word in word_list:
        for i in range(word_length):
            intermediate = word[:i] + "*" + word[i+1:]
            adjacency[intermediate].append(word)

    queue = deque([(begin_word, 1)])
    visited = {begin_word}

    while queue:
        current_word, level = queue.popleft()
        for i in range(word_length):
            intermediate = current_word[:i] + "*" + current_word[i+1:]
            for neighbor in adjacency[intermediate]:
                if neighbor == end_word:
                    return level + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, level + 1))
            adjacency[intermediate] = []

    return 0


def main() -> None:
    """Main function demonstrating word ladder BFS."""
    examples = [
        ("hit", "cog", ["hot", "dot", "dog", "lot", "log", "cog"]),
        ("hit", "cog", ["hot", "dot", "dog", "lot", "log"]),
        ("a", "c", ["a", "b", "c"]),
    ]
    for begin, end, word_list in examples:
        print(f"{begin} -> {end}: {ladder_length(begin, end, word_list)}")


if __name__ == "__main__":
    main()

from __future__ import annotations

from collections import defaultdict, deque
from typing import Dict, List


def build_graph(words: List[str]) -> Dict[str, List[str]]:
    graph: Dict[str, List[str]] = defaultdict(list)
    for word in words:
        for i in range(len(word)):
            pattern = word[:i] + "*" + word[i+1:]
            graph[pattern].append(word)
    return graph


def find_ladders(beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
    if endWord not in wordList:
        return []
    wordList.append(beginWord)
    graph = build_graph(wordList)
    distances: Dict[str, int] = {beginWord: 0}
    queue = deque([beginWord])

    while queue:
        current = queue.popleft()
        for i in range(len(current)):
            pattern = current[:i] + "*" + current[i+1:]
            for neighbor in graph[pattern]:
                if neighbor not in distances:
                    distances[neighbor] = distances[current] + 1
                    queue.append(neighbor)

    results: List[List[str]] = []
    if endWord not in distances:
        return results

    def backtrack(path: List[str]) -> None:
        word = path[-1]
        if word == endWord:
            results.append(path.copy())
            return
        for i in range(len(word)):
            pattern = word[:i] + "*" + word[i+1:]
            for neighbor in graph[pattern]:
                if distances.get(neighbor, float("inf")) == distances[word] + 1:
                    path.append(neighbor)
                    backtrack(path)
                    path.pop()

    backtrack([beginWord])
    return results


def main() -> None:
    beginWord = "hit"
    endWord = "cog"
    wordList = ["hot", "dot", "dog", "lot", "log", "cog"]
    solutions = find_ladders(beginWord, endWord, wordList)
    print("Word ladders:", solutions)


if __name__ == "__main__":
    main()

from __future__ import annotations

from typing import List


def exist(board: List[List[str]], word: str) -> bool:
    """Return True if the word exists in the board by adjacent character path."""
    rows = len(board)
    cols = len(board[0]) if rows else 0
    visited: List[List[bool]] = [[False] * cols for _ in range(rows)]

    def dfs(r: int, c: int, index: int) -> bool:
        if index == len(word):
            return True
        if (
            r < 0
            or c < 0
            or r >= rows
            or c >= cols
            or visited[r][c]
            or board[r][c] != word[index]
        ):
            return False

        visited[r][c] = True
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            if dfs(r + dr, c + dc, index + 1):
                return True
        visited[r][c] = False
        return False

    for row in range(rows):
        for col in range(cols):
            if dfs(row, col, 0):
                return True
    return False


def main() -> None:
    """Main function demonstrating word search in a board."""
    board = [
        ["A", "B", "C", "E"],
        ["S", "F", "C", "S"],
        ["A", "D", "E", "E"],
    ]
    print("ABCCED ->", exist(board, "ABCCED"))
    print("SEE ->", exist(board, "SEE"))
    print("ABCB ->", exist(board, "ABCB"))


