    main()

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Optional


@dataclass
class TrieNode:
    children: Dict[str, "TrieNode"] = None
    word: Optional[str] = None

    def __post_init__(self) -> None:
        if self.children is None:
            self.children = {}


def build_trie(words: List[str]) -> TrieNode:
    root = TrieNode()
    for word in words:
        node = root
        for char in word:
            node = node.children.setdefault(char, TrieNode())
        node.word = word
    return root


def find_words(board: List[List[str]], words: List[str]) -> List[str]:
    if not board or not board[0] or not words:
        return []

    root = build_trie(words)
    rows, cols = len(board), len(board[0])
    found: List[str] = []

    def dfs(r: int, c: int, node: TrieNode) -> None:
        char = board[r][c]
        if char not in node.children:
            return
        next_node = node.children[char]
        if next_node.word:
            found.append(next_node.word)
            next_node.word = None

        board[r][c] = "#"
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and board[nr][nc] != "#":
                dfs(nr, nc, next_node)
        board[r][c] = char

    for i in range(rows):
        for j in range(cols):
            dfs(i, j, root)

    return found


def main() -> None:
    board = [
        ["o", "a", "a", "n"],
        ["e", "t", "a", "e"],
        ["i", "h", "k", "r"],
        ["i", "f", "l", "v"],
    ]
    words = ["oath", "pea", "eat", "rain"]
    print("Found words:", find_words(board, words))


if __name__ == "__main__":
    main()

from __future__ import annotations


def convert(s: str, num_rows: int) -> str:
    """Return the zigzag conversion of the string."""
    if num_rows == 1 or num_rows >= len(s):
        return s

    rows: list[str] = ["" for _ in range(num_rows)]
    current_row = 0
    direction = 1

    for char in s:
        rows[current_row] += char
        if current_row == 0:
            direction = 1
        elif current_row == num_rows - 1:
            direction = -1
        current_row += direction

    return "".join(rows)


def main() -> None:
    examples = [
        ("PAYPALISHIRING", 3),
        ("PAYPALISHIRING", 4),
        ("A", 1),
    ]
    for s, rows in examples:
        print(f"{s}, {rows} -> {convert(s, rows)}")


if __name__ == "__main__":
    main()
